tree/blob/6a163584ccc696d903a1d677cbce57a2328b297b/content/books/zizhi-tongjian/vol-292/year-0955/part-02/sources/library/songshi-262-zan-jurun-identity/source.txt", "note": "《宋史》卷262·昝居润传（电子总题名待校），段落 songshi-9c6e46fee832-p058103；已核上下文及传主，纸本及异文待核。", "id": "0289d227-c082-58f6-9e42-f3103fd3713b"}, {"title": "宋史·卷262·昝居润传·秦凤行营", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6a163584ccc696d903a1d677cbce57a2328b297b/content/books/zizhi-tongjian/vol-292/year-0955/part-02/sources/library/songshi-262-zan-jurun-qinfeng/source.txt", "note": "《宋史》卷262·昝居润传·秦凤行营，段落 songshi-9c6e46fee832-p058104；已核上下文及传主，纸本及异文待核。", "id": "ecd19b19-6076-5a65-b009-e5a000b82b49"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6a163584ccc696d903a1d677cbce57a2328b297b/content/books/zizhi-tongjian/vol-292/year-0955/part-02/sources/library/tongjian-292-955-qinfeng-first-order/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003469；电子底本待考，分段待核", "id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"title": "新五代史·卷三十一", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6a163584ccc696d903a1d677cbce57a2328b297b/content/books/zizhi-tongjian/vol-292/year-0955/part-02/sources/library/xinwudaishi-31-wangpu-essay/source.txt", "note": "《新五代史》卷三十一，段落 xin-wudaishi-b08f244b9241-p001135；EPUB电子本，纸本及异文待核", "id": "082aab12-88d8-54b6-8017-7f170724add4"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ff2825de598cdd120a803b4e1262b653a990b093/content/books/zizhi-tongjian/vol-292/year-0955/part-01/sources/library/tongjian-292-955-february/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003468；电子底本待考，分段待核", "id": "abc8b9bf-3ba7-5530-8dcc-e609704d6924"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ff2825de598cdd120a803b4e1262b653a990b093/content/books/zizhi-tongjian/vol-292/year-0955/part-01/sources/library/jiuwudaishi-115-luyankou-defense/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002726；EPUB电子本，纸本及异文待核", "id": "cdf3557b-ad52-58db-a213-0692004a273f"}, {"title": "旧五代史·卷128·王朴传·校书郎与澶州记室", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/jiuwudaishi-128-wangpu-career/source.txt", "note": "《旧五代史》卷128·王朴传·校书郎与澶州记室，段落 jiu-wudaishi-205deb4a7860-p002978；已核上下文及传主，纸本及异文待核。", "id": "56c253e7-33d4-535c-843c-0efb1f179155"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "严续", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明四年条所见人物：严续。", "biography": null, "status": "draft", "id": "57b5cb9f-cb31-5e6a-87de-6363e1836468"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "赵季札", "aliases": ["趙季札"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀客省使。952年受孟昶之命赴梓州，慰抚吏民。生卒年未载。", "biography": null, "status": "draft", "id": "faffdaed-5d02-5666-a551-64c61d7f86a3"}, {"name": "韩继勋", "aliases": ["韓繼勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：韩继勋，医官使、曾事藩邸者。", "biography": null, "status": "draft", "id": "3327c23e-cf6f-54fb-a0c6-0077fa06e1ec"}, {"name": "王万迪", "aliases": ["王萬迪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀凤州刺史。955年赵季札巡视边备后，向孟昶批评王万迪与雄武节度使韩继勋不能御敌。这里只保存他人评价，不据此确认其必无将才。生卒年未载。", "biography": null, "status": "draft", "id": "c768f68c-0d47-5041-aff0-16cad9d22206"}, {"name": "王昭远", "aliases": ["王昭遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "成都人，后蜀官员。年少时跟随僧人智諲进入孟知祥府中，后来被留下侍奉孟昶；《新五代史》《宋史》记当时十三岁。948年由茶酒库使任通奏使、知枢密院事，获委机务和府库财物支配。没有据十三岁反推出生年。", "biography": null, "status": "draft", "id": "49c83873-4e4d-515e-9f4b-ebbf460d53fd"}, {"name": "王朴", "aliases": ["王樸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "东平人，原任校书郎。951年任柴荣镇宁军掌书记。《旧五代史》记他字文伯，在后汉乾祐年间中进士，后来进入澶州幕府。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aef64c13-19ef-556c-96f1-dd9e8fb91844"}, {"name": "王溥（后周宋初）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "949年为秘书郎，在河中平定后劝郭威焚毁涉及朝臣、藩镇的往来书信，《宋史》王溥传也记此事。与901年条所载同名王溥分开建档。生卒年留待具体原文补录。", "biography": null, "status": "draft", "id": "13d3b7ec-869a-5019-ac41-39e5abcd2df3"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "王景（后晋耀州团练使）", "aliases": ["王景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "掖县人，曾任相州刺史。范延光叛乱时，他拒绝服从范延光。938年任耀州团练使。生卒年未载。", "biography": null, "status": "draft", "id": "95c5e667-cc89-51aa-862e-471795aa6956"}, {"name": "昝居润", "aliases": ["昝居潤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高唐人，后周客省使。955年奉柴荣命与向训、王景同赴秦凤。《宋史》记其善书计，早年为枢密院小吏，后任军器库使，高平战功后任客省使；同一秦凤役中任行营都监。生卒年留待后续史料补录。", "biography": null, "status": "draft", "id": "e5f47220-de7a-5c34-88bc-0d953279124e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

